<span class="line"><span style="color:#C792EA;">const</span><span style="color:#BABED8;"> h </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> box</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">offsetHeight</span><span style="color:#89DDFF;">;</span><span style="color:#676E95;font-style:italic;">   // 再次强制布局</span></span>
